-- 星笺 STELLAR INK 种子数据（与前端展示用的示例内容对齐）
-- 适用：MySQL 8.0+，需先执行 01_schema.sql
--
-- ⚠️ 执行前请先在客户端选中目标数据库（同 01_schema.sql 的说明）
--
-- 用法示例：mysql -uroot -p 数据库名 < 02_init-data.sql
-- 说明：使用 INSERT IGNORE，可重复执行不产生重复数据
--       种子账号：stellar / stellar123（BCrypt 存储）
-- =============================================================

-- ⚠️ 必须显式声明客户端字符集，否则本文件里的中文会整片变成乱码：
--   mysql 客户端的默认值 auto 按操作系统 locale 推断，容器内 locale 是 POSIX/C → 退回 latin1，
--   UTF-8 中文被当 latin1 读入后转存，网页上就显示成「æ×–â®¹」这类。
--   Docker 的 mysql 镜像自动执行 /docker-entrypoint-initdb.d/*.sql 时不带 --default-character-set，
--   所以这一行是给自动初始化兜底的（手动导入时同样有效）。
SET NAMES utf8mb4;

