-- -------------------------------------------------------------
-- 开发手记（作者：拾星人 / 夜航员 / 渡口）
-- word_count 先留 0，由文件末尾的 UPDATE 按正文统一计算
-- -------------------------------------------------------------
INSERT IGNORE INTO `post` (`id`, `user_id`, `title`, `content`, `tags`, `word_count`, `status`, `glow`, `view_count`, `created_at`, `updated_at`) VALUES
(16, 1, '一次 23 秒的请求：Redis 超时是怎么把接口挂住的',
 '那天的日志只有两行红字，我却盯着看了半小时。\n\n`GET /tags 200 23076ms` —— 接口没报错，返回 200，只是慢得像卡住。同一时刻另一行写着：读取 Redis 缓存失败，回源业务数据，`Redis command timed out`。\n\n第一反应是 Redis 挂了。可再往下看，Redis 只超时了 3 秒，从报错到客户端重连成功，中间那 16 秒是整台服务器完全不可达的时间。所有请求都卡在这一段里，等网络回来才一起结束。23 秒 = 3 秒的 Redis 超时 + 20 秒的没人告诉我该放弃。\n\n问题不在 Redis，而在三个默认值。\n\n一是 MySQL 连接串没写超时。Connector/J 的 `connectTimeout` 与 `socketTimeout` 默认都是 0，意思是无限等；网络断在那里，代码只能等操作系统放弃，Windows 上大约 21 秒。\n二是缓存读的 3 秒超时太长。旁路缓存的职责是能加速就加速、不能就立刻回源，读一次等 3 秒，等于把缓存的小故障放大成用户能感觉到的卡顿。\n三是连接池拿不到连接时要等 60 秒，线程就静静排在那儿。\n\n改法很朴素：连接串补上 `connectTimeout=3000&socketTimeout=15000`；Druid 的 `max-wait` 从 60 秒收到 5 秒，保活探测也给 3 秒上限；Redis 读超时开发环境降到 500 毫秒、生产 1 秒。\n\n改完我没有等下一次抖动，因为我知道它一定还会来。但它再来的时候，最坏的结果从“用户等 20 秒”变成“用户等半秒，然后数据老老实实从数据库读出来”。\n\n深夜的教训：分布式系统里最贵的不是超时，是没有超时。',
 '开发,后端,性能', 0, 1, 41, 268, '2026-08-04 23:40:00', '2026-08-04 23:40:00'),
(17, 1, '把后端挂在公网上的那些天',
 '把自己写的服务挂在公网上，是一件很安静的事：没有报警，没有异常日志，一切看起来都在正常工作，直到你意识到“能访问”这件事本身就是漏洞。\n\n那天排查缓存超时，顺手扫了一下那台机器对外开放的端口。结果有点凉：Nacos 的 8848 能连，配置中心没开鉴权，任何能路由过去的人都能读到配置；Redis 的 6379 能连，发一个 PING 就回了 PONG，没有密码；MySQL 的 3306 也能连，账号还是 root 加六位数字。\n\n最要命的是读到了什么：配置中心里躺着 JWT 的签名密钥。这个密钥由网关和所有服务共用，token 里带着角色字段，而网关只验签、读角色，不查库。也就是说，拿到密钥的人可以自己签一个角色为站长的 token，然后删文章、改任何人的权限、审友链——不需要知道任何人的密码，也不需要登录。\n\n修复顺序比修复本身更重要：\n\n第一步，先把端口从公网收回。安全组只放行自己的出口 IP，本机开发改走 SSH 隧道。这一条做完，风险立刻降一个量级。\n第二步，改口令：MySQL 换强口令并给业务建专用账号，只授权需要的库；Redis 设 requirepass 且只监听内网；配置中心打开鉴权，别再用默认口令。\n第三步，把密钥从配置中心删掉，只留环境变量注入，然后轮换。轮换会让所有已登录用户掉线，所以放最后做。\n\n写完之后我重读了一遍自己的部署文档，发现它一直在说“敏感项走环境变量”，只是我在某次图省事的时候，把密钥粘进了配置中心。\n\n安全不是加了很多东西，而是少犯一次“图省事”。',
 '开发,安全,复盘', 0, 1, 57, 402, '2026-08-07 22:15:00', '2026-08-07 22:15:00'),
(18, 1, '左侧竖栏改成顶栏：一级导航从 11 项砍到 6 项',
 '导航是一个博客最容易被忽视、也最能暴露信息架构问题的地方。原来左边一条竖栏挂了十一项：此刻、执笔、星图、寻星、笔记、复核、流星、光谱、回声、星链、星籍。每隔一段时间加一项，加到后来我自己都要数一遍。\n\n这次全部推倒重来，只问一个问题：它是不是一类内容的主入口？\n\n按这个标准，光谱先出局。标签只是文章的一个筛选维度，它应该长在星图里，和年份一起叠加筛选，而不是单占一个页面。复核同理：复核队列本来就是“我自己的已发布笔记”的一个筛选档，于是它成了我的笔记里的第二个视图，筛选状态还写进了 URL，可以分享、可以刷新。星籍的内容其实是账号页里的一个面板，合并之后顺手删掉了印章、全站口径、格言和三个占位链接——它们只是看起来丰富。\n\n执笔和寻星不需要占位置：执笔是动作，收进右上角的主色按钮，只有作者看得到；寻星是工具，收成一枚放大镜图标。\n\n于是十一项变成六项：此刻、星图、笔记、流星、回声、星链。数字变小了，但每一页都更容易被点到。\n\n视觉上顺手做了另一件事：把竖栏换成顶栏，并且未滚动时完全透明，直接压在星野上；滚动超过 40 像素才浮出底色和一条分隔线。导航不该一直提醒你它在那里。\n\n删掉的入口都留了重定向，老书签不会撞到 404。删东西的时候，对旧链接客气一点，是基本的礼貌。',
 '开发,前端,设计', 0, 1, 33, 197, '2026-08-10 23:05:00', '2026-08-10 23:05:00'),
(19, 1, '三个让我白干半天的前端坑',
 '这一年前端踩过的坑里，有三个的共同点是：不报错，只是安静地不生效。\n\n第一个：组件模板多根节点，`v-show` 不生效。Vue 3 允许一个组件有多个根节点，但此时父组件传下来的指令（`v-show`、`class`、`style`）没有明确该落到谁身上，于是 Vue 只在控制台给一句警告，然后什么也不做。我那次的现象是“弹层开关点了没反应”，排查两小时才想起这个文件有两个根 div。规矩很简单：模板保持单根。\n\n第二个：入场动画的 `animation-fill-mode: both` 把 `opacity` 钉死在 1。全站统一的入场动画是“从透明浮上来”，用了 `both` 之后，动画结束的样式会一直保留。后来我想用 JS 动态改透明度做渐隐，怎么改都不动——因为静态样式压不过动画的终态。要么别给这个元素加入场动画，要么同时加上 `animation: none`。\n\n第三个：祖先元素上的 `filter` 或 `transform` 会成为 `position: fixed` 后代的包含块。这不是 Vue 的问题，是 CSS 规范：有 `filter`/`transform` 的祖先会成为固定定位的参照。于是本该贴在视口右下角的悬浮按钮，被关在了那个 `filter` 元素里面，跟着它一起滚动。修法是别在这些祖先上写 `filter`/`transform`，或者把悬浮件挪到外面去。\n\n三个坑都不是“不会写”，而是“不知道它不会报错”。前端最花时间的从来不是语法，是这类静默失效——所以后来我养成一个习惯：任何“看起来没生效”的样式，先看 DOM 和计算样式，别靠截图猜。',
 '开发,前端,踩坑', 0, 1, 46, 315, '2026-08-13 21:50:00', '2026-08-13 21:50:00'),
(20, 1, '标签精确匹配：从 LIKE 到 FIND_IN_SET',
 '标签是逗号分隔的一列字符串，最早的筛选是这么写的：`WHERE tags LIKE %vue%`。\n\n小数据量下它一直没出问题，直到有人写了 `vue3`，于是搜 `vue` 会把它一起捞出来；再往后有 `vueuse`、`vue-router`，一个标签开始互相污染。\n\n改法是换成 MySQL 的 `FIND_IN_SET`：`WHERE FIND_IN_SET(#{tag}, tags) > 0`。它按“逗号分隔成员”做精确匹配，`vue` 只匹配 `vue`，不会顺带匹配 `vue3`。代价是它用不上索引，但博客这个体量，全表扫几十行和走索引的差别可以忽略。\n\n顺手补了两条约束：标签本身不允许包含逗号（否则整个匹配语义会崩），写入时统一 trim 去重。\n\n这类问题的通用教训是：把结构塞进字符串，早晚会在查询上还回来。真要做复杂标签，应该建关联表；只是在“写起来轻”和“查得准”之间，`FIND_IN_SET` 是一个诚实的折中——前提是你知道它的边界在哪里。',
 '开发,后端,MySQL', 0, 1, 22, 143, '2026-08-16 23:30:00', '2026-08-16 23:30:00'),
(21, 4, '中文 curl 发请求为什么返回 500',
 '用 git-bash 的 curl 测一个中文接口，返回 500，日志里说 JSON 解析失败，可我盯着那串看着完全正常的 JSON 看了很久。\n\n原因不在 JSON，在编码。git-bash 在 Windows 上按 GBK 把命令行里的中文拼成字节发出去，服务端按 UTF-8 解析请求体，于是中文变成乱码，反序列化自然失败。\n\n三个可用的解法，按省事程度排：\n\n第一，把请求体写进一个 UTF-8 文件，然后用 `--data-binary @body.json` 发。文件是 UTF-8 就一定是 UTF-8，不再受终端编码影响。\n第二，用 Node 写三行 `fetch` 发请求——编辑器保存的文件本来就是 UTF-8。\n第三，如果一定要在命令行里写中文，先把终端切成 UTF-8（`chcp 65001`），但这条最不稳定，取决于终端和 curl 版本。\n\n我现在的习惯是：只要 body 里有中文，就写文件。反正这个文件还能进版本库，当作接口的样例请求。\n\n顺便一提，同样的问题也会出现在“日志里中文乱码”上——大多数时候不是日志框架的错，是终端在看别的编码。',
 '开发,工具,踩坑', 0, 1, 18, 121, '2026-08-19 20:40:00', '2026-08-19 20:40:00'),
(22, 1, 'JWT 无状态之后，登出为什么还要 Redis',
 'JWT 是无状态的：服务端不存会话，只验签名。这个特性让水平扩展很舒服，也带来一个尴尬的问题——登出怎么办？\n\n签名仍然有效，谁拿到那串 token 谁就能继续用，直到它自己过期。改密码更麻烦：密码都换了，旧 token 还能用七天。\n\n我们的做法是加一份撤销列表：登出和改密时，把这张 token 的 SHA-256 摘要写进 Redis，TTL 设成它的剩余寿命。网关在路由之前查一次这个列表，命中就返回 401。token 原文不进缓存，只进摘要——这样即使缓存泄露，也拿不到可用的凭证。\n\n设计的三个细节值得记下来：\n\n一，Redis 不可用时返回 503，不允许故障放行。否则一次缓存抖动就等于把撤销名单丢了，已登出的 token 会重新生效。\n二，登录与注册不查这张表。否则 Redis 一挂，连重新登录恢复的机会都没有，等于把出口也锁上了。\n三，摘要的 TTL 等于 token 剩余寿命，过期自动清理，不需要额外的定时任务。\n\n代价是每个请求都多一次 Redis 查询。但撤销检查只读一个短小的布尔值，超时压到 1 秒以内，比它挡住的那些风险划算得多。',
 '开发,后端,鉴权', 0, 1, 29, 176, '2026-08-22 23:15:00', '2026-08-22 23:15:00'),
(23, 5, '520KB 的编辑器，我让它只在一个页面出现',
 '技术笔记的编辑区用的是 CodeMirror 6：光标所在行显示源码，其余行把标记折叠掉、直接渲染成结果——这也是我坚持不用 textarea 的原因，这种行内渲染没法用纯文本域实现。\n\n代价是体积：七个包加起来 520KB，gzip 之后 180KB。对一个首屏只有一百多 KB 的博客来说，把编辑器打进主包是不可接受的。\n\n处理方式是把这条依赖限制在一个页面里：编辑器组件只在笔记编辑页通过 `defineAsyncComponent` 动态引入，打包器会把它切成独立 chunk，只有真正打开编辑页才下载。同时在项目约定里写死一条硬规则——任何其它页面都不许 import 它。规则要写成文档，因为“顺手 import 一下”是几个月后最容易发生的事故。\n\n验证方式也很直接：构建完看 chunk 列表，确认编辑器那个 chunk 存在，而首屏的 index chunk 没有变大。数字比感觉可靠。\n\n这件事的意义不在于省了多少流量，而在于把“贵的东西”和“常用的东西”分开。写作是低频动作，它值得被懒加载；而阅读是高频动作，读者不该为作者的编辑器付费。',
 '开发,前端,性能', 0, 1, 26, 158, '2026-08-25 22:30:00', '2026-08-25 22:30:00'),
(24, 1, '把博客的加载动画，改成了一次呼吸',
 '原来的加载动画是一圈转动的点，像所有网站那样。看久了会觉得它有点急。\n\n改的时候我只做了一件事：把节奏放慢，让它像一次呼吸——吸气亮起，呼气暗下，周期大约四秒。它不再催促任何人，只是安静地说明“还在路上”。\n\n顺带把动效做成了全局基线：所有动画在系统开启“减少动态效果”时全部停掉，包括星野、漂流瓶和这圈呼吸。这一条写在基础样式里，新组件不用各自再实现一遍。\n\n还有一个细节：页面首屏的主题在 HTML 解析的第一时间就确定下来（内联脚本先读本地偏好，没存过就跟系统走），所以选过破晓主题的人刷新时，不会先闪过一层夜色。\n\n我一直觉得，动效是界面的语气。同样的等待，用急促的方式表达是焦虑，用呼吸的方式表达是耐心。博客是慢的地方，语气应该一致。',
 '开发,前端,动效', 0, 1, 61, 430, '2026-08-28 23:50:00', '2026-08-28 23:50:00');

-- -------------------------------------------------------------
-- 夜晚随笔（作者：夜航员 / 渡口 / 拾星人）
-- -------------------------------------------------------------
INSERT IGNORE INTO `post` (`id`, `user_id`, `title`, `content`, `tags`, `word_count`, `status`, `glow`, `view_count`, `created_at`, `updated_at`) VALUES
(25, 4, '凌晨四点的便利店，和它的第九位客人',
 '凌晨四点的便利店，是世界上唯一还在营业的诚实。\n\n关东煮的汤在锅里翻着小泡，店员在补货，动作很轻，像是怕吵醒谁。那天晚上我数了数，前后一共进来九个人：三个代驾，两个夜班护士，一个抱着电脑的年轻人，一个买了两节电池的老人，一个只买了一瓶水的女孩，还有我。\n\n没有人说话。我们非常默契地保持着一种关系——共享一盏灯，但不打扰彼此。\n\n第九位客人是我。我买了一罐温热的咖啡，站在窗边，看外面的路面被路灯切成一条一条。城市在夜里会变得很小：先收拢成一条街，再收拢成一盏灯，最后收拢成一个还亮着的窗。\n\n出门的时候，店员说了句“慢走”。那是那天我听到的唯一一句人话，也是最好的一句。',
 '城市,速写', 0, 1, 52, 288, '2026-08-31 04:10:00', '2026-08-31 04:10:00'),
(26, 1, '母亲寄来的橘子，还带着南方的霜',
 '母亲寄来一箱橘子，箱子上写着我的名字，字很大，像是怕快递员看不见。\n\n打开的时候，橘子上还带着一层薄薄的白霜——那是南方的清晨留在上面的东西。我剥了一个，皮很厚，指甲缝里立刻全是香气。这个香气我认得：小时候冬天写作业，母亲会在旁边剥橘子，一瓣一瓣放在作业本的右上角。\n\n后来我离开了那座城市，也离开了那种冬天。这里的冬天不下霜，只有连绵的雨，和永远不够亮的太阳。\n\n我给母亲打电话，说橘子收到了，很甜。她在电话那头说：不太甜吧，今年雨水多。我说，真的很甜。\n\n有些话在电话里说不出口，就写在文章里：谢谢你记得我爱吃这个。',
 '生活,随笔', 0, 1, 74, 512, '2026-09-02 22:40:00', '2026-09-02 22:40:00'),
(27, 1, '雨停之后，我数了数窗上的水痕',
 '雨停之后，我数了数窗上的水痕。一共十一条，最长的一条从上到下走完了整块玻璃，像一次完整的旅行。\n\n数完之后我意识到，我已经很久没有这样无所事事地待着了。所有时间都在被填满：通勤填满播客，吃饭填满视频，睡前填满信息流。连“休息”都被安排成了项目。\n\n于是我把手机倒扣在桌上，继续看那十一条水痕。第十二条出现了，很细，走得很慢。\n\n那天晚上我什么也没做，只写了两句话。但那两句话，是那一周里唯一没有被任何通知打断过的句子。',
 '速写,夜晚', 0, 1, 38, 205, '2026-09-05 23:20:00', '2026-09-05 23:20:00'),
(28, 5, '地铁末班车上，所有人都在假装不累',
 '末班车是没有伪装的车厢。\n\n白天大家还愿意挺着背，晚上十一点半之后，所有肩膀都松了下来。有人把头靠在车窗上，随着列车轻微地晃；有人把包抱在怀里，像抱着一件必须保护好的东西；对面那个穿西装的男生，领带解到一半就睡着了，手机还亮着，停在一条没发出去的消息上。\n\n没有人抱怨。我们只是安静地坐着，各自消化自己那一天。\n\n到站前有一小段路会经过地面，车厢里会突然亮起来。那一瞬间窗户变成镜子，我看见满满一车厢疲惫的脸，也看见自己的。\n\n门开了，所有人站起来，重新把背挺直，走出车厢，走进夜色。第二天早上，他们还会是那些看起来什么都不缺的人。',
 '城市,沉思', 0, 1, 44, 261, '2026-09-08 23:55:00', '2026-09-08 23:55:00'),
(29, 1, '养一盆不会开花的植物',
 '我养了一盆不会开花的植物。买的时候老板说它不开花，只是长叶子，很好养。\n\n第一年它长了两片新叶。第二年长得快一些，围着花盆铺了半圈。它从不在某个特定的日子给你惊喜，但你每周看它一眼，都能看出一点变化。\n\n我慢慢发现，我更喜欢它。会开花的植物把一年的期待都押在那几天，开完就结束了；而它把时间均匀地花在每一片叶子上，谁也不知道哪一天算成功。\n\n写作也差不多。写下的大多数段落不会成为名句，它们只是安静地铺在那里，把结构撑起来。真正让一棵植物像植物的，不是花，是那些不开花的部分。',
 '生活,速写', 0, 1, 30, 168, '2026-09-11 22:05:00', '2026-09-11 22:05:00');

-- -------------------------------------------------------------
-- 技术笔记（标本册）：正文用「## 现象 / ## 环境 / ## 排查 / ## 结论 / ## 参考」，
-- 读取端据此自动生成目录，并把「结论」当作列表摘要
-- verified_at 刻意留了三种状态：近日验证 / 超过 180 天（已过期）/ 从未验证
-- -------------------------------------------------------------
INSERT IGNORE INTO `note` (`id`, `user_id`, `title`, `content`, `tags`, `note_type`, `visibility`, `status`, `word_count`, `view_count`, `verified_at`, `created_at`, `updated_at`) VALUES
(11, 1, 'GET /tags 偶发 20 秒以上：Redis 命令超时',
 '## 现象\n\n`GET /tags` 返回 200，但耗时 23076ms。同一时刻日志里有：\n\n```text\nRedisCache - 读取 Redis 缓存失败，回源业务数据 key=...:version:tag\nerror=org.springframework.dao.QueryTimeoutException: Redis command timed out\n```\n\n随后是 Lettuce 的重连日志，重连成功后同一接口稳定在 25-130ms。\n\n## 环境\n\n- Spring Boot 3.2.12 + Spring Data Redis（Lettuce）+ Druid + MySQL 8.0.46\n- 开发机通过公网访问服务器上的 Redis / MySQL（这是关键前提）\n- Redis `timeout: 3s`，JDBC URL 未设置 `connectTimeout` / `socketTimeout`\n\n## 排查\n\n1. 先怀疑 Redis 变慢：但报错只花了 3 秒（命令超时到点），不是 Redis 内部慢。\n2. 再看时间线：Redis 报错 14:45:09，重连成功 14:45:25，中间 16 秒主机完全不可达。请求从 14:45:06 开始，23 秒基本等于“网络恢复时刻 - 请求开始时刻”。\n3. 于是问题不在缓存层，而在“没人告诉代码该放弃”：Connector/J 的 `connectTimeout` 与 `socketTimeout` 默认都是 0（无限等），只能等操作系统放弃，Windows 上约 21 秒。\n4. 顺带确认缓存本身没有放大问题：`RedisCache` 有 30 秒失败退避，失败后不再反复打 Redis。\n\n## 结论\n\n缓存读超时必须远短于业务超时：Redis 读超时开发 500ms / 生产 1s，超时即回源；同时给 JDBC 补上显式超时，别让“无限等”成为默认行为。\n\n```yaml\nspring:\n  data:\n    redis:\n      timeout: 500ms\n      connect-timeout: 2s\n```\n\n```text\njdbc:mysql://...?connectTimeout=3000&socketTimeout=15000\n```\n\n## 参考\n\n- Connector/J 官方文档：Configuration Properties（connectTimeout / socketTimeout 默认 0）\n- Lettuce：命令超时与连接看门狗（ConnectionWatchdog）的重连行为',
 'java,redis,mysql,性能', 'FIX', 'PUBLIC', 1, 0, 120, '2026-01-12 22:10:00', '2026-01-10 22:10:00', '2026-01-12 22:10:00'),
(12, 1, 'Connector/J 默认不设连接超时，链路异常时只能等操作系统',
 '## 现象\n\n数据库相关接口在链路抖动时出现 10-23 秒的“无日志卡顿”：线程没有异常、没有慢 SQL 记录，只是停在那里，直到网络恢复才继续。\n\n## 环境\n\n- MySQL Connector/J 8.x + Druid 1.2.20，MySQL 8.0.46\n- 连接串由配置拼接，未显式指定任何网络超时\n\n## 排查\n\n1. 打开 Druid 的 `remove-abandoned` 与 SQL 日志，确认没有连接泄漏，也没有长事务。\n2. 在链路正常时压测：P95 只有几十毫秒，说明逻辑本身没问题。\n3. 对比抖动时刻的日志发现：卡住的时间与“Redis 报错到重连成功”的窗口完全重合。\n4. 查 Connector/J 默认值：`connectTimeout=0`、`socketTimeout=0`，即**不超时**。此时 TCP 层只能等系统重试耗尽，Windows 默认约 21 秒。\n\n## 结论\n\n连接串里把两个超时写死，让失败可控且可观测：`connectTimeout=3000&socketTimeout=15000`。注意 `socketTimeout` 是“读超时”，长查询会被中断，取值要大于最慢的合法查询。\n\n```text\njdbc:mysql://host:3306/db?connectTimeout=3000&socketTimeout=15000\n```\n\n## 参考\n\n- MySQL Connector/J：Configuration Properties\n- Druid：maxWait 与 validationQueryTimeout 的语义区别',
 'java,mysql,配置', 'PITFALL', 'PUBLIC', 1, 0, 96, '2026-02-08 22:40:00', '2026-02-08 22:40:00', '2026-02-08 22:40:00'),
(13, 1, 'Druid max-wait 默认 60 秒：拿不到连接时线程静默排队',
 '## 现象\n\n并发上来时接口变慢但没有任何异常，日志里既没有慢 SQL，也没有连接池耗尽告警；请求最终都能成功，只是要等很久。\n\n## 环境\n\n- Druid 1.2.20，`max-active: 10`，`max-wait: 60000`\n- 单实例开发环境，MySQL 与 Redis 都在远端\n\n## 排查\n\n1. 先看是否有慢 SQL：`mybatis-plus` 的 SQL 日志显示每条都在几十毫秒内，排除。\n2. 再看线程栈：多个请求线程停在 `DruidDataSource.pollLast`，即在等可用连接。\n3. 结论是连接被“网络卡住”的请求长期占着，池子满了之后其余请求就静静排队，最长排 60 秒。\n\n## 结论\n\n池子的等待时间要按“最坏情况可接受”来设，而不是默认值：`max-wait: 5000`，并把保活探测也限制住（`validation-query-timeout: 3`），否则抖动时连 SELECT 1 都能挂住。宁可快速失败并返回可识别的错误，也不要让线程无声排队一分钟。\n\n```yaml\nspring:\n  datasource:\n    druid:\n      max-wait: 5000\n      validation-query: SELECT 1\n      validation-query-timeout: 3\n```\n\n## 参考\n\n- Druid 官方配置说明：maxWait / validationQueryTimeout',
 'java,druid,数据库', 'PITFALL', 'PUBLIC', 1, 0, 88, '2026-03-06 21:30:00', '2026-03-06 21:30:00', '2026-03-06 21:30:00'),
(14, 1, 'Vue 组件多根节点时 v-show 不生效（只给一行警告）',
 '## 现象\n\n父组件里写 `<Child v-show="visible" />`，切换 visible 时弹层没有任何反应，控制台只有一句 warning，页面其它部分完全正常。\n\n## 环境\n\n- Vue 3.5，`<script setup>` 单文件组件\n- 该组件模板有两个并列的根元素\n\n## 排查\n\n1. 先怀疑 `visible` 没变：打印 watcher，值确实在变。\n2. 用开发者工具看 DOM：根节点上根本没有 `display: none`，说明指令没有落到任何元素上。\n3. 回看控制台那句被忽略的警告，指向「Extraneous non-props attributes / 多根节点组件上的指令无法自动继承」。\n\n## 结论\n\n组件模板保持单根节点。多根组件不会报错，但父级传下来的 `v-show` / `class` / `style` 无法决定落到哪个根上，于是被静默忽略。需要多根时，把根换成一个包裹元素，或显式 `v-bind="$attrs"` 到目标节点。\n\n```vue\n<template>\n  <div class="wrapper">\n    <header />\n    <main />\n  </div>\n</template>\n```\n\n## 参考\n\n- Vue 3 文档：Fallthrough Attributes（多根节点组件的注意事项）',
 'vue,前端,踩坑', 'PITFALL', 'PUBLIC', 1, 0, 74, '2026-04-02 23:10:00', '2026-04-02 23:10:00', '2026-04-02 23:10:00'),
(15, 1, '动画的 animation-fill-mode: both 会把 opacity 钉死在终态',
 '## 现象\n\n入场动画（从透明浮上来）播完之后，用 JS 改元素的 `opacity` 做渐隐，样式写了但元素纹丝不动。\n\n## 环境\n\n- 原生 CSS 动画 + Vue scoped 样式\n- 全局入场类 `.reveal { animation: rise .7s var(--ease) both; }`\n\n## 排查\n\n1. 确认 JS 确实改了内联样式：Elements 面板能看到 `style="opacity: .2"`。\n2. 看 Computed 面板：生效值仍是 1，来源显示为动画。\n3. 结论：`both` 让动画保留结束帧（`to { opacity: 1 }`），而动画的声明优先于普通样式，所以内联样式压不过它。\n\n## 结论\n\n要么别给需要动态透明度的元素加入场动画，要么显式关掉它：`animation: none`。也可以把 `both` 换成 `forwards` 之外的组合，但只要动画终态还在生效，静态样式就没机会。\n\n```css\n.fade-target { animation: none; }\n```\n\n## 参考\n\n- MDN：animation-fill-mode（forwards / backwards / both 的保留规则）',
 'css,前端,动效', 'PITFALL', 'PUBLIC', 1, 0, 70, '2026-04-28 22:50:00', '2026-04-28 22:50:00', '2026-04-28 22:50:00'),
(16, 1, '祖先元素的 filter / transform 会成为 position: fixed 的包含块',
 '## 现象\n\n右下角的「回到顶部」按钮本该固定在视口右下角，实际却跟着内容一起滚动，滚动到某处就消失了。\n\n## 环境\n\n- 原生 CSS；按钮的祖先链上有一层带 `filter` 的容器（做模糊玻璃效果）\n\n## 排查\n\n1. 检查按钮自身：`position: fixed; right: 26px; bottom: 26px` 写得没问题。\n2. 逐层删祖先样式，删到某个容器的 `filter: blur()` 时按钮立刻归位。\n3. 查规范确认：`filter`（以及 `transform`、`perspective`、`will-change` 等）会让元素成为 fixed 后代的包含块。\n\n## 结论\n\n需要 fixed 悬浮件时，别把 `filter` / `transform` 写在它的祖先上；已经写了就把悬浮件挪到这些容器之外。`backdrop-filter` 同理，做毛玻璃时优先加在悬浮件自己身上。\n\n```css\n/* 悬浮件自己模糊，而不是让祖先模糊 */\n.fab { backdrop-filter: blur(12px); }\n```\n\n## 参考\n\n- CSS Containment / Filter Effects 规范：containing block for fixed positioned descendants',
 'css,前端,踩坑', 'PITFALL', 'PUBLIC', 1, 0, 80, '2026-05-22 21:40:00', '2026-05-22 21:40:00', '2026-05-22 21:40:00'),
(17, 1, 'Sa-Token JWT 无状态模式：登出为什么还要一份撤销列表',
 '## 现象\n\n无状态 JWT 的固有矛盾：登出、改密之后，旧 token 的签名依然有效，谁拿着它谁就能继续访问。\n\n## 环境\n\n- Sa-Token 1.44.0，`StpLogicJwtForStateless`\n- 网关 WebFlux + Reactive Redis，业务服务 Servlet + Redis\n\n## 排查\n\n1. 验证现象：登录拿到 token，登出后继续用它请求受保护接口，依然 200。\n2. 尝试过“能不能把用户踢下线”：无状态模式没有会话表，服务端无处标记。\n3. 也验证了另一种做法（把 token 存 Redis 当白名单）的代价：等于退回有状态，水平扩展优势没了。\n\n## 结论\n\n用「令牌摘要撤销表」：登出与改密时把 token 的 SHA-256 摘要写入 Redis，TTL 取令牌剩余寿命；网关在路由前查一次，命中即 401。Redis 不可用时返回 503，不允许故障放行。\n\n```text\nSET revoke:<sha256(token)> 1 EX <remaining-seconds>\n```\n\n## 参考\n\n- Sa-Token 文档：JWT 无状态模式与“注销”的语义限制\n- 我们的实现：`common-core` 的撤销写入 + 网关的 Reactive 校验',
 'java,sa-token,鉴权,redis', 'TIL', 'PUBLIC', 1, 0, 92, '2026-06-15 22:20:00', '2026-06-15 22:20:00', '2026-06-15 22:20:00'),
(18, 1, 'FIND_IN_SET 做逗号分隔标签的精确匹配',
 '## 现象\n\n按标签筛选文章时，搜 `vue` 会连 `vue3`、`vueuse` 一起带出来，筛选结果偏大。\n\n## 环境\n\n- MySQL 8.0，`post.tags` 是逗号分隔的 `VARCHAR(200)`\n- 原实现：`WHERE tags LIKE CONCAT(char(37), #{tag}, char(37))`\n\n## 排查\n\n1. 复现：造两条数据 `vue` 与 `vue3`，搜 `vue` 命中两条 —— LIKE 是子串匹配，不是成员匹配。\n2. 加边界（`%,vue,%`）只能解决两头，`vue,vue3` 这种同列多值仍然误判。\n3. 试 `FIND_IN_SET(tag, tags) > 0`：精确按逗号成员匹配，符合预期。\n\n## 结论\n\n标签筛选统一改成 `FIND_IN_SET(#{tag}, tags) > 0`，并在写入侧约束标签不能含逗号。注意它无法走索引，数据量大了应该改成关联表 + 联合索引。\n\n```sql\nSELECT * FROM post WHERE status = 1 AND FIND_IN_SET(?, tags) > 0\n```\n\n## 参考\n\n- MySQL 文档：FIND_IN_SET(str, strlist)\n- 反例：LIKE 子串匹配在分组标签上的误判',
 'mysql,sql,标签', 'TIL', 'PUBLIC', 1, 0, 86, '2026-07-06 23:00:00', '2026-07-06 23:00:00', '2026-07-06 23:00:00'),
(19, 1, 'Nacos 开了配置中心却没开鉴权：密钥等于公开',
 '## 现象\n\n一次排查网络问题的时候顺手扫了服务器端口，发现 8848 从公网可直连；再用默认口令参数请求配置接口，**无凭据就读到了配置内容**，其中包含 JWT 签名密钥。\n\n## 环境\n\n- Nacos 2.x，`NACOS_AUTH_ENABLE=false`，命名空间为自定义 ID\n- 同一台机器上还跑着 MySQL 3306 与 Redis 6379，均对公网开放（Redis 无密码）\n\n## 排查\n\n1. 确认可达性：`Test-NetConnection` 三个端口全部可连；Redis 发 PING 直接回 PONG。\n2. 读取配置：`GET /nacos/v1/cs/configs?dataId=...` 返回明文 YAML，里面有 `sa-token.jwt-secret-key`。\n3. 评估影响：token 里带角色字段，网关只验签 + 读角色、不查库，因此持有密钥即可自签一个站长身份的 token。\n\n## 结论\n\n修复顺序比修复本身重要：① 安全组收回 3306/6379/8848，只放行自己的出口 IP，开发改走 SSH 隧道；② 换强口令、Redis 设 requirepass、Nacos 开鉴权并改掉默认口令；③ 把密钥从配置中心删除，只走环境变量，最后再轮换（会导致所有人掉线）。\n\n```text\nNACOS_AUTH_ENABLE=true\nNACOS_AUTH_TOKEN=<32 字节以上的随机串>\n```\n\n## 参考\n\n- Nacos 官方：鉴权与认证配置\n- 本项目约定：密钥只从环境变量读取，配置中心不得保存',
 '安全,nacos,运维', 'FIX', 'PUBLIC', 1, 0, 110, '2026-07-28 22:10:00', '2026-07-26 22:10:00', '2026-07-26 22:10:00'),
(20, 1, 'Vite：把 520KB 的编辑器限制在一个懒加载页面里',
 '## 现象\n\n引入 CodeMirror 6 之后构建产物里出现一个 519.81 kB（gzip 180.46 kB）的 chunk，如果被首屏引用，博客的首屏体积会变成三倍。\n\n## 环境\n\n- Vite 7 + Vue 3，路由全部懒加载\n- 依赖：`@codemirror/*` + `@lezer/*` 共 7 个包\n\n## 排查\n\n1. 直接 import 后构建，观察 chunk 列表：编辑器被合进编辑页 chunk 还是首屏 chunk。\n2. 结论是“只要有一个非懒加载模块引用它，它就会进入首屏依赖图”。\n\n## 结论\n\n只在编辑页用 `defineAsyncComponent` 引入编辑器组件，并在项目约定里写死：其它页面一律不许 import。构建后核对首屏 chunk 大小没有增长。\n\n```js\nconst MarkdownEditor = defineAsyncComponent(() => import(\"@/components/editor/MarkdownEditor.vue\"))\n```\n\n## 参考\n\n- Vite 文档：动态导入与代码分割\n- Vue 文档：defineAsyncComponent',
 'vite,vue,性能,构建', 'TIL', 'PUBLIC', 1, 0, 78, NULL, '2026-08-16 22:30:00', '2026-08-16 22:30:00'),
(21, 1, '我的写作流水线：从念头到发射',
 '## 现象\n\n（私有笔记示例：只在自己手里、不出现在任何公开列表与搜索里。）\n\n念头太多、发布太少，草稿箱里堆了二十几条半成品，最后都不了了之。\n\n## 环境\n\n- 一个 nightly 写作博客，一位作者，零截稿日\n\n## 排查\n\n1. 统计了三周的草稿：真正卡住的是第二段，不是标题。\n2. 原因是想在第二段就把道理讲完，于是越写越重。\n3. 改成“先把场景写出来，结论留到深夜再补”。\n\n## 结论\n\n固定一个流程：念头先扔进流星备忘录，成段的进草稿，能收尾的当晚发射。第二段只写场景，不写结论。\n\n## 参考\n\n- 本站写作提示卡（`api/mock.js` 的 PROMPTS）',
 '写作,流程', 'TIL', 'PRIVATE', 1, 0, 0, '2026-09-01 23:30:00', '2026-09-01 23:30:00', '2026-09-01 23:30:00');

