INSERT IGNORE INTO `post_comment` (`id`, `post_id`, `user_id`, `content`, `status`, `created_at`, `updated_at`) VALUES
(3, 16, 4, '“分布式系统里最贵的不是超时，是没有超时”——这句我要贴到工位上。我们上周也遇到一模一样的 20 秒卡顿，查了两天才发现是连接池的 maxWait。', 1, '2026-09-15 00:20:00', '2026-09-15 00:20:00'),
(4, 16, 1, '同源问题。后来我们把 max-wait 一起收了，宁可快速失败，也要让错误可识别。', 1, '2026-09-15 00:35:00', '2026-09-15 00:35:00'),
(5, 16, 6, '请问 Redis 超时降到 500ms 之后，缓存命中率有下降吗？', 1, '2026-09-15 09:10:00', '2026-09-15 09:10:00'),
(6, 16, 1, '几乎没有下降。只有链路抖动的那几秒会回源，其余时间照常命中。', 1, '2026-09-15 12:40:00', '2026-09-15 12:40:00'),
(7, 17, 5, '看得后背发凉。我们组的测试库也一直挂在公网上，明天就去收端口。', 1, '2026-09-13 23:10:00', '2026-09-13 23:10:00'),
(8, 17, 1, '顺序别反：先收端口，再改口令，最后轮换密钥。密钥一换，所有人都会掉线。', 1, '2026-09-13 23:25:00', '2026-09-13 23:25:00'),
(9, 17, 7, '“安全不是加了很多东西，而是少犯一次图省事”，记下了。', 1, '2026-09-14 08:50:00', '2026-09-14 08:50:00'),
(10, 18, 4, '删入口比加入口难得多。留重定向这一步很贴心，老书签还能用。', 1, '2026-09-12 23:40:00', '2026-09-12 23:40:00'),
(11, 19, 6, '多根节点那个我踩过，排查了三个小时，最后发现是控制台一行警告。', 1, '2026-09-11 22:30:00', '2026-09-11 22:30:00'),
(12, 19, 5, 'filter 导致 fixed 失效这条是 CSS 规范，不是框架的锅，很多人不知道。', 1, '2026-09-11 23:05:00', '2026-09-11 23:05:00'),
(13, 21, 7, 'chcp 65001 那招我试过，时灵时不灵，还是把 body 写成文件靠谱。', 1, '2026-09-09 21:30:00', '2026-09-09 21:30:00'),
(14, 22, 5, '撤销列表存摘要而不是原文，这个细节很关键。', 1, '2026-09-08 22:15:00', '2026-09-08 22:15:00'),
(15, 23, 4, '520KB 换成懒加载，这个思路可以用在任何低频但很重的功能上。', 1, '2026-09-06 23:20:00', '2026-09-06 23:20:00'),
(16, 24, 6, '呼吸那版动画我很喜欢，等页面的时候不焦虑了。', 1, '2026-09-04 22:40:00', '2026-09-04 22:40:00'),
(17, 26, 5, '橘子那段看哭了。我妈也总说“今年不太甜”。', 1, '2026-08-27 00:10:00', '2026-08-27 00:10:00'),
