-- -------------------------------------------------------------
-- 字数：按正文去掉空白字符后的长度计算，与后端写入时的口径保持一致
-- （只为内容扩充包的行计算，不动既有种子行的手写字数）
-- -------------------------------------------------------------
UPDATE `post` SET `word_count` = CHAR_LENGTH(REPLACE(REPLACE(REPLACE(`content`, '\r', ''), '\n', ''), ' ', ''))
WHERE `id` BETWEEN 16 AND 29 AND `content` IS NOT NULL;

UPDATE `note` SET `word_count` = CHAR_LENGTH(REPLACE(REPLACE(REPLACE(`content`, '\r', ''), '\n', ''), ' ', ''))
WHERE `id` BETWEEN 11 AND 21 AND `content` IS NOT NULL;
